    <div class="options-container">
        <div class="option-item" data-type="reasonable">$1</div>
        <div class="option-item" data-type="erotic">$2</div>
        <div class="option-item" data-type="nsfw">$3</div>
        <div class="option-item" data-type="rebellious">$4</div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const optionItems = document.querySelectorAll('.option-item');

            optionItems.forEach(item => {
                item.addEventListener('click', (event) => {
                    const itemElement = event.currentTarget;
                    // 防止在“已复制”状态下重复操作
                    if (itemElement.classList.contains('copied')) {
                        return;
                    }

                    const textToCopy = itemElement.textContent.trim();
                    const originalHTML = itemElement.innerHTML;

                    navigator.clipboard.writeText(textToCopy).then(() => {
                        // 复制成功后的反馈
                        itemElement.innerHTML = '✓ 已复制';
                        itemElement.classList.add('copied');

                        // 1.5秒后恢复原样
                        setTimeout(() => {
                            itemElement.innerHTML = originalHTML;
                            itemElement.classList.remove('copied');
                        }, 1500);
                    }).catch(err => {
                        console.error('无法复制文本: ', err);
                        itemElement.innerHTML = '复制失败';
                         setTimeout(() => {
                            itemElement.innerHTML = originalHTML;
                        }, 1500);
                    });
                });
            });
        });
    </script>

